// Hanken Grotesk — the portal's typeface — for PDFs drawn with jsPDF, so a
// report reads like the page it came from (owner, 11/2026: "is the font in
// the table the right font"). Static TTFs (SIL Open Font License, from
// @expo-google-fonts/hanken-grotesk) as base64; jsPDF has only Helvetica,
// Times and Courier built in.
//
//   useHanken(doc) registers "Hanken" (normal, bold) and "HankenXB" (800).

import type { jsPDF } from "jspdf";
const REGULAR = "";
const BOLD = "";
const EXTRABOLD = "";

export function useHanken(doc: jsPDF): void {
  doc.addFileToVFS("HankenGrotesk-Regular.ttf", REGULAR);
  doc.addFont("HankenGrotesk-Regular.ttf", "Hanken", "normal");
  doc.addFileToVFS("HankenGrotesk-Bold.ttf", BOLD);
  doc.addFont("HankenGrotesk-Bold.ttf", "Hanken", "bold");
  doc.addFileToVFS("HankenGrotesk-ExtraBold.ttf", EXTRABOLD);
  doc.addFont("HankenGrotesk-ExtraBold.ttf", "HankenXB", "normal");
}
